const owner = ref[1] === me;
const isHaistDev = authStr.indexOf('haist dev') !== -1;
const coordInDept = isCoord && !!bookingDept && myDepts.indexOf(bookingDept) !== -1;
if (!(owner || isHaistDev || coordInDept)) return bad('NOT_YOURS',
  'BLOCKED - "' + title + '" was booked by ' + ((by && by[1].trim()) || 'someone else')
  + ', and you do not have authority to move it. Say exactly that and stop.');

