let outLocation = ev.location || '';
let outAttendees = (ev.attendees || []).filter(a => a.resource).map(a => ({ email: a.email }));
const ROOMS = {'Studio 1':'hitproductions.net_3737303833303637363538@resource.calendar.google.com','Studio 2':'c_18871bprki2umhrkjc4qcaldse1f8@resource.calendar.google.com','Studio 3':'c_1886me03bdcrki5bhu8vddknl472k@resource.calendar.google.com','Studio 4':'c_188e94dapvbp8jvrjmuga6qbof826@resource.calendar.google.com','Studio 5':'c_18889v3glj9cqiotg8j95jaqmdhmm@resource.calendar.google.com','Studio 6':'c_18838qt2ru30ein7gcefjiarplkre@resource.calendar.google.com','Studio 7':'c_188dupcj6cqfaipohqffj07ruq8de@resource.calendar.google.com','Studio 8':'c_18863v8hd6f42isegdh9i30psuo9q@resource.calendar.google.com','Studio A':'c_18843dclutqm6hl9nbeg002phapfu@resource.calendar.google.com','Studio B':'c_1881vgb66tkpujjelnn3rniugd9pk@resource.calendar.google.com','Studio C':'c_188797f37eu9ujs6ldpf3smn78joc@resource.calendar.google.com','Studio D':'c_18801gc6ck77gho7jl0e1fug94u92@resource.calendar.google.com','Studio E':'c_1888r4bbc2lhqgndmprism70nft64@resource.calendar.google.com','Studio F':'c_188em7d58podeju3i8q6juqlufkls@resource.calendar.google.com','Studio M':'c_1885k4adm87fqjd2j3j2usqftph5c@resource.calendar.google.com','M1':'c_1889v46vd62fkjk3i7r1hsfem7tcm@resource.calendar.google.com','M2':'c_1883ui6lnfc9ogt2hrmg57a30n72q@resource.calendar.google.com','M3':'c_188d7dkqgnfs6hu4iunlu5ogftct0@resource.calendar.google.com','M4':'c_18869nhmsj2uki8mljoi48v1cj7l4@resource.calendar.google.com','M5':'c_1889h30ci9noqjcbnoogad9qk75vq@resource.calendar.google.com','M6':'c_188f9gnq0a9tehf4g9ja57l83c0ts@resource.calendar.google.com','M7':'c_1880r9hhk9c2agpbko87o7fojosh0@resource.calendar.google.com','M8':'c_1884cu2cc84iujsjnu03s21f0ct9q@resource.calendar.google.com','Salin':'c_1887hh5rsv6q4gt8hnu6ered170lg@resource.calendar.google.com','Katha':'c_1881169pcpn12gsnm6i7sc0gjk7gk@resource.calendar.google.com','Likha':'c_1886t6cjgrq0ihgpime01uibcqsg6@resource.calendar.google.com','Lobby':'c_188227mpeagjuhi7gqlgns1di14be@resource.calendar.google.com'};
const newRooms = String(REQ.new_rooms || '').split(/,|\band\b|&|\+/i).map(r => r.trim()).filter(Boolean);
